const COLORS = {
  bg: "#0c1015",
  panel: "#141a22",
  panelAlt: "#0f141b",
  border: "#242e3a",
  text: "#e9edf1",
  muted: "#7c8895",
  chalk: "#f2ece0",
  gold: "#d4a12a",
  expected: "#3b4a5a",
  tierNormal: "#4f9d69",
  tierModerate: "#d4a12a",
  tierSmall: "#c15a4f",
  tierInsufficient: "#3a4149",
};

const BUCKET_X = { "<20": 10, "20-29": 25, "30-39": 35, "40-49": 45, "50-59": 55, "60+": 65 };
const BUCKETS = ["<20", "20-29", "30-39", "40-49", "50-59", "60+"];

function tierColor(tag) {
  if (tag === "normal") return COLORS.tierNormal;
  if (tag === "moderate") return COLORS.tierModerate;
  if (tag === "small") return COLORS.tierSmall;
  return COLORS.tierInsufficient;
}

function tierLabel(tag) {
  if (tag === "normal") return "40+ attempts";
  if (tag === "moderate") return "10\u201339 attempts";
  if (tag === "small") return "5\u20139 attempts \u2014 small sample";
  return "under 5 \u2014 insufficient sample";
}

function DistanceRuler({ cells }) {
  const w = 640, h = 210, baselineY = 120, scale = 2.6;
  const minKp = Math.min(100, ...cells.filter(c => c.kp != null).map(c => c.kp));
  const maxKp = Math.max(100, ...cells.filter(c => c.kp != null).map(c => c.kp));
  const topPad = Math.max(20, (maxKp - 100) * scale + 34);
  const botPad = Math.max(20, (100 - minKp) * scale + 34);
  const totalH = topPad + botPad;

  return (
    <svg viewBox={`0 0 ${w} ${totalH}`} width="100%" style={{ display: "block", overflow: "visible" }}>
      <line x1={30} y1={topPad} x2={w - 10} y2={topPad} stroke={COLORS.border} strokeWidth={1} strokeDasharray="3 4" />
      <text x={24} y={topPad + 4} textAnchor="end" fontSize="11" fill={COLORS.muted} fontFamily="IBM Plex Sans, sans-serif">100</text>
      <line x1={30} y1={topPad} x2={w - 10} y2={topPad + 0.0001} stroke="none" />
      {BUCKETS.map((b) => {
        const x = 30 + (BUCKET_X[b] / 70) * (w - 50);
        return (
          <g key={b}>
            <line x1={x} y1={topPad - 6} x2={x} y2={topPad + 6} stroke={COLORS.muted} strokeWidth={1.5} />
            <text x={x} y={totalH - 4} textAnchor="middle" fontSize="12" fill={COLORS.text} fontFamily="Oswald, sans-serif" fontWeight="600">
              {b}
            </text>
          </g>
        );
      })}
      {cells.map((c) => {
        const x = 30 + (BUCKET_X[c.b] / 70) * (w - 50);
        if (c.kp == null) {
          return (
            <g key={c.b}>
              <circle cx={x} cy={topPad} r={3} fill={COLORS.tierInsufficient} />
              <text x={x} y={topPad - 14} textAnchor="middle" fontSize="11" fill={COLORS.muted} fontFamily="IBM Plex Sans, sans-serif">
                \u2014
              </text>
            </g>
          );
        }
        const barH = (c.kp - 100) * scale;
        const barY = c.kp >= 100 ? topPad - barH : topPad;
        const absH = Math.max(Math.abs(barH), 3);
        const color = tierColor(c.tag);
        return (
          <g key={c.b}>
            <rect x={x - 14} y={barY} width={28} height={absH} fill={color} opacity={0.9} rx={2} />
            <text
              x={x} y={c.kp >= 100 ? barY - 8 : barY + absH + 16}
              textAnchor="middle" fontSize="13" fontWeight="700" fill={COLORS.text}
              fontFamily="Oswald, sans-serif"
            >
              {c.kp.toFixed(1)}
            </text>
            <text
              x={x} y={c.kp >= 100 ? barY - 8 : barY + absH + 16}
              dy={13}
              textAnchor="middle" fontSize="9.5" fill={COLORS.muted} fontFamily="IBM Plex Sans, sans-serif"
            >
              {c.att} att
            </text>
          </g>
        );
      })}
    </svg>
  );
}

function TrajectoryChart({ seasons }) {
  const sorted = [...seasons].sort((a, b) => a.y - b.y);
  return (
    <ResponsiveContainer width="100%" height={220}>
      <LineChart data={sorted} margin={{ top: 10, right: 16, bottom: 0, left: -14 }}>
        <CartesianGrid stroke={COLORS.border} strokeDasharray="3 4" vertical={false} />
        <XAxis dataKey="y" stroke={COLORS.muted} fontSize={11} tickLine={false} axisLine={{ stroke: COLORS.border }} />
        <YAxis stroke={COLORS.muted} fontSize={11} tickLine={false} axisLine={false} width={36} />
        <ReferenceLine y={100} stroke={COLORS.muted} strokeDasharray="4 4" />
        <Tooltip
          contentStyle={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, borderRadius: 6, fontFamily: "IBM Plex Sans, sans-serif", fontSize: 12 }}
          labelStyle={{ color: COLORS.text, fontWeight: 600 }}
          itemStyle={{ color: COLORS.gold }}
          formatter={(value, name, props) => [`${value} Kick+`, `${props.payload.att} att`]}
          labelFormatter={(y) => `${y} season`}
        />
        <Line
          type="monotone" dataKey="kp" stroke={COLORS.gold} strokeWidth={2}
          dot={(props) => {
            const { cx, cy, payload, index } = props;
            const filled = payload.tier === "ranked";
            return (
              <circle key={`dot-${index}`} cx={cx} cy={cy} r={4.5}
                fill={filled ? COLORS.gold : COLORS.panel}
                stroke={COLORS.gold} strokeWidth={1.5} />
            );
          }}
          activeDot={{ r: 6, fill: COLORS.gold }}
        />
      </LineChart>
    </ResponsiveContainer>
  );
}

export default function KickPlusExplorer() {
  const [query, setQuery] = useState("");
  const [tab, setTab] = useState("career");
  const [selected, setSelected] = useState(DATA.career[0].p);

  const careerSorted = useMemo(
    () => [...DATA.career].sort((a, b) => b.kp - a.kp),
    []
  );
  const consistentSorted = useMemo(
    () => DATA.career.filter((r) => r.sd != null).sort((a, b) => a.sd - b.sd),
    []
  );
  const bestSeasons = useMemo(
    () => [...DATA.seasons].filter((s) => s.tier === "ranked").sort((a, b) => b.kp - a.kp).slice(0, 60),
    []
  );

  const filteredCareer = careerSorted.filter((r) =>
    r.p.toLowerCase().includes(query.toLowerCase())
  );

  const player = DATA.career.find((r) => r.p === selected);
  const seasons = DATA.seasons.filter((s) => s.p === selected);
  const profile = DATA.profile[selected] || [];
  const diffPct = player ? (100 * (player.kp - 100)) / 100 : 0;

  const listToShow =
    tab === "career" ? filteredCareer :
    tab === "consistent" ? consistentSorted.filter((r) => r.p.toLowerCase().includes(query.toLowerCase())) :
    bestSeasons.filter((r) => r.p.toLowerCase().includes(query.toLowerCase()));

  return (
    <div style={{ background: COLORS.bg, color: COLORS.text, minHeight: "100%", fontFamily: "IBM Plex Sans, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Oswald:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');
        * { box-sizing: border-box; }
        ::-webkit-scrollbar { width: 8px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.border}; border-radius: 4px; }
      `}</style>

      <div style={{ padding: "28px 28px 8px 28px", borderBottom: `1px solid ${COLORS.border}` }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
          <h1 style={{ fontFamily: "Oswald, sans-serif", fontWeight: 700, fontSize: 26, margin: 0, letterSpacing: 0.5 }}>
            Kick+
          </h1>
          <span style={{ color: COLORS.muted, fontSize: 13.5 }}>
            era- and distance-adjusted field goal performance, 2001\u20132025
          </span>
        </div>
        <div style={{ display: "flex", gap: 4, marginTop: 18 }}>
          {[
            ["career", "Career Kick+"],
            ["consistent", "Most Consistent"],
            ["season", "Best Seasons"],
          ].map(([key, label]) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              style={{
                background: tab === key ? COLORS.panel : "transparent",
                color: tab === key ? COLORS.chalk : COLORS.muted,
                border: `1px solid ${tab === key ? COLORS.border : "transparent"}`,
                borderBottom: tab === key ? `2px solid ${COLORS.gold}` : "2px solid transparent",
                padding: "8px 14px",
                fontSize: 13,
                fontFamily: "IBM Plex Sans, sans-serif",
                fontWeight: 500,
                cursor: "pointer",
                borderRadius: "6px 6px 0 0",
              }}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "280px 1fr", minHeight: 640 }}>
        <div style={{ borderRight: `1px solid ${COLORS.border}`, background: COLORS.panelAlt, display: "flex", flexDirection: "column" }}>
          <div style={{ padding: 14, borderBottom: `1px solid ${COLORS.border}` }}>
            <div style={{ position: "relative" }}>
              <Search size={14} color={COLORS.muted} style={{ position: "absolute", left: 10, top: 10 }} />
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search kickers"
                style={{
                  width: "100%", background: COLORS.panel, border: `1px solid ${COLORS.border}`,
                  borderRadius: 6, padding: "8px 10px 8px 30px", color: COLORS.text, fontSize: 13,
                  fontFamily: "IBM Plex Sans, sans-serif", outline: "none",
                }}
              />
            </div>
          </div>
          <div style={{ overflowY: "auto", flex: 1 }}>
            {listToShow.map((r, i) => {
              const isSeason = tab === "season";
              const name = r.p;
              const active = name === selected;
              return (
                <button
                  key={isSeason ? `${r.p}-${r.y}` : r.p}
                  onClick={() => setSelected(name)}
                  style={{
                    width: "100%", textAlign: "left", background: active ? COLORS.panel : "transparent",
                    border: "none", borderLeft: active ? `3px solid ${COLORS.gold}` : "3px solid transparent",
                    padding: "10px 14px", cursor: "pointer", display: "flex",
                    justifyContent: "space-between", alignItems: "center", gap: 8,
                  }}
                >
                  <span style={{ display: "flex", flexDirection: "column", minWidth: 0 }}>
                    <span style={{ fontSize: 13.5, color: COLORS.text, fontWeight: active ? 600 : 400, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                      {i + 1}. {name}
                    </span>
                    {isSeason && (
                      <span style={{ fontSize: 11, color: COLORS.muted }}>{r.y} \u00b7 {r.att} att</span>
                    )}
                    {tab === "consistent" && (
                      <span style={{ fontSize: 11, color: COLORS.muted }}>SD {r.sd}</span>
                    )}
                  </span>
                  <span style={{ fontFamily: "Oswald, sans-serif", fontWeight: 600, color: COLORS.gold, fontSize: 14, flexShrink: 0 }}>
                    {r.kp.toFixed(1)}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {player && (
          <div style={{ padding: 28, overflowY: "auto" }}>
            <div style={{ marginBottom: 26 }}>
              <div style={{ fontSize: 14, color: COLORS.muted, textTransform: "none" }}>{player.p}</div>
              <div style={{ display: "flex", alignItems: "baseline", gap: 14 }}>
                <span style={{ fontFamily: "Oswald, sans-serif", fontWeight: 700, fontSize: 68, color: COLORS.chalk, lineHeight: 1 }}>
                  {player.kp.toFixed(1)}
                </span>
                <span style={{ fontSize: 13, color: COLORS.muted, letterSpacing: 1 }}>KICK+</span>
              </div>
              <div style={{ fontSize: 13, color: COLORS.muted, marginTop: 6 }}>
                {player.att} attempts \u00b7 {player.seasons} seasons ({player.nRanked} ranked)
                {player.sd != null && <> \u00b7 consistency SD {player.sd}</>}
              </div>
            </div>

            <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 20, marginBottom: 20 }}>
              <div style={{ fontSize: 13, color: COLORS.muted, marginBottom: 14 }}>
                Actual vs. expected field goals made ({diffPct >= 0 ? "+" : ""}{diffPct.toFixed(1)}%)
              </div>
              {["made", "exp"].map((key) => {
                const val = key === "made" ? player.made : player.exp;
                const max = Math.max(player.made, player.exp);
                const pct = (val / max) * 100;
                return (
                  <div key={key} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
                    <span style={{ width: 62, fontSize: 12, color: COLORS.muted }}>{key === "made" ? "Actual" : "Expected"}</span>
                    <div style={{ flex: 1, background: COLORS.panelAlt, borderRadius: 4, height: 22 }}>
                      <div style={{ width: `${pct}%`, height: "100%", background: key === "made" ? COLORS.gold : COLORS.expected, borderRadius: 4 }} />
                    </div>
                    <span style={{ width: 54, fontSize: 12.5, textAlign: "right", fontFamily: "Oswald, sans-serif" }}>{val.toFixed ? val.toFixed(1) : val}</span>
                  </div>
                );
              })}
            </div>

            <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 20, marginBottom: 20 }}>
              <div style={{ fontSize: 13, color: COLORS.muted, marginBottom: 6 }}>Where the value comes from, by distance</div>
              <DistanceRuler cells={profile} />
              <div style={{ display: "flex", gap: 16, marginTop: 10, flexWrap: "wrap" }}>
                {["normal", "moderate", "small", "insufficient"].map((tag) => (
                  <div key={tag} style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ width: 9, height: 9, borderRadius: 2, background: tierColor(tag), display: "inline-block" }} />
                    <span style={{ fontSize: 11, color: COLORS.muted }}>{tierLabel(tag)}</span>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: 20 }}>
              <div style={{ fontSize: 13, color: COLORS.muted, marginBottom: 6 }}>Season by season</div>
              <TrajectoryChart seasons={seasons} />
              <div style={{ display: "flex", gap: 16, marginTop: 4 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ width: 9, height: 9, borderRadius: 5, background: COLORS.gold, display: "inline-block" }} />
                  <span style={{ fontSize: 11, color: COLORS.muted }}>ranked season (20+ att)</span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ width: 9, height: 9, borderRadius: 5, background: COLORS.panel, border: `1.5px solid ${COLORS.gold}`, display: "inline-block" }} />
                  <span style={{ fontSize: 11, color: COLORS.muted }}>small sample (10\u201319 att)</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
